const CameraFlashIcon: React.FC<{ size?: number; className?: string; iconClassName?: string }> = ({ size = 20, className = "", iconClassName = "" }) => {
  const ref = useRef(null);
  const isInView = useInView(ref, { amount: 0.5 });
  const [hasFlashed, setHasFlashed] = useState(false);

  useEffect(() => {
    if (isInView && !hasFlashed) {
      setHasFlashed(true);
      // Reset after animation so it can flash again if scrolled back
      const timer = setTimeout(() => setHasFlashed(false), 2000);
      return () => clearTimeout(timer);
    }
  }, [isInView]);

  return (
    <div ref={ref} className={`relative inline-flex items-center justify-center ${className}`}>
      <Camera size={size} className={iconClassName} />

      {/* Flash Effect Layer */}
      <AnimatePresence>
        {hasFlashed && (
          <motion.div
            initial={{ opacity: 0, scale: 0.5 }}
            animate={{ 
              opacity: [0, 1, 0], 
              scale: [0.8, 2.5],
              filter: ["blur(0px)", "blur(10px)"]
            }}
            exit={{ opacity: 0 }}
            transition={{ duration: 0.4, ease: "easeOut" }}
            className="absolute inset-0 bg-white rounded-full pointer-events-none z-10"
          />
        )}
      </AnimatePresence>

      {/* Lens Flare Dot */}
      <AnimatePresence>
        {hasFlashed && (
          <motion.div
            initial={{ opacity: 0, x: -10, y: -10 }}
            animate={{ 
              opacity: [0, 0.8, 0],
              x: [0, 20],
              y: [0, 20],
            }}
            transition={{ duration: 0.6, delay: 0.1 }}
            className="absolute w-1 h-1 bg-blue-200 rounded-full blur-[2px] z-20"
          />
        )}
      </AnimatePresence>
    </div>
  );
};

