const scrollToId = (id: string) => {
  const element = document.getElementById(id.replace('#', ''));
  if (element) {
    element.scrollIntoView({ behavior: 'smooth' });
  } else if (id === 'home' || id === '#home') {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }
};

