    e.preventDefault();
    scrollToId(href);
    setIsMobileMenuOpen(false);
  };

  return (
    <nav className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${isScrolled ? 'bg-[#050505]/90 backdrop-blur-md py-4 shadow-xl' : 'bg-transparent py-6'}`}>
